\begin{tikzpicture}[x=9mm,y=9mm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{quantityBlue}{HTML}{D4E8FF}
\path[use as bounding box] (-0.1,-0.1) rectangle (4.9,5.1);
\fill[quantityBlue] (0,4.2) rectangle (2,5);
\fill[quantityBlue] (2.8,3) rectangle (3.3,5);
\fill[quantityBlue] (0,1.2) rectangle (2,2);
\fill[quantityBlue] (2.8,0) rectangle (3.3,2);
\foreach \x in {0,2.8}{\draw[black,line width=0.8pt] (\x,3) rectangle +(2,2);\draw[black,line width=0.8pt] (\x,0) rectangle +(2,2);}
\foreach \y in {3.4,3.8,4.2,4.6}{\draw[black,line width=0.25pt] (0,\y)--(2,\y);}
\foreach \x in {3.3,3.8,4.3}{\draw[black,line width=0.25pt] (\x,3)--(\x,5);}
\foreach \y in {0.4,0.8,1.2,1.6}{\draw[black,line width=0.25pt] (0,\y)--(2,\y);\draw[black,line width=0.25pt] (2.8,\y)--(4.8,\y);}
\foreach \x in {0.5,1,1.5}{\draw[black,line width=0.25pt] (\x,0)--(\x,2);}
\foreach \x in {3.3,3.8,4.3}{\draw[black,line width=0.25pt] (\x,0)--(\x,2);}
\node[black,font=\fontsize{10}{12}\selectfont] at (2.4,4) {$+$};
\node[black,font=\fontsize{10}{12}\selectfont] at (2.4,1) {$+$};
\end{tikzpicture}

